ALTER TABLE ai_workbench.messages ADD COLUMN message_kind text NOT NULL DEFAULT 'TEXT', ADD COLUMN store_query_status text;
ALTER TABLE ai_workbench.commands ADD COLUMN route_commit_deadline timestamptz, ADD COLUMN route_result text;
ALTER TABLE ai_workbench.commands DROP CONSTRAINT commands_check;
ALTER TABLE ai_workbench.commands DROP CONSTRAINT commands_operation_check;
ALTER TABLE ai_workbench.commands DROP CONSTRAINT commands_state_check;
ALTER TABLE ai_workbench.commands ADD CONSTRAINT commands_check CHECK ((((operation = 'conversation_create'::text) AND (state = 'COMPLETE'::text) AND (user_message_id IS NULL) AND (planner_invocation_id IS NULL)) OR ((operation = ANY (ARRAY['chat_message_plan'::text, 'chat_intent_route'::text])) AND (user_message_id IS NOT NULL) AND (source_sequence IS NOT NULL) AND (planner_invocation_id IS NOT NULL) AND (member_id IS NOT NULL) AND (work_scope IS NOT NULL) AND ((state = 'FAILED_BEFORE_DISPATCH'::text) OR ((planner_input_hash IS NOT NULL) AND (planner_model_profile IS NOT NULL) AND (planner_started_at IS NOT NULL) AND (planner_deadline IS NOT NULL))) AND ((operation <> 'chat_intent_route'::text) OR (route_commit_deadline IS NOT NULL) OR ((state = 'FAILED_BEFORE_DISPATCH'::text) AND (planner_model_profile IS NULL) AND (planner_input_hash IS NULL) AND (planner_started_at IS NULL) AND (planner_deadline IS NULL) AND (assistant_message_id IS NOT NULL)))) OR ((operation = 'chat_store_overview'::text) AND (state = 'COMPLETE'::text) AND (member_id IS NOT NULL) AND (user_message_id IS NOT NULL) AND (source_sequence IS NOT NULL) AND (assistant_message_id IS NOT NULL) AND (planner_invocation_id IS NULL) AND (planner_input_hash IS NULL) AND (planner_model_profile IS NULL) AND (route_result = 'STORE_OVERVIEW'::text))));
ALTER TABLE ai_workbench.commands ADD CONSTRAINT commands_operation_check CHECK ((operation = ANY (ARRAY['conversation_create'::text, 'chat_message_plan'::text, 'chat_intent_route'::text, 'chat_store_overview'::text])));
ALTER TABLE ai_workbench.commands ADD CONSTRAINT commands_route_result_check CHECK (((route_result IS NULL) OR (route_result = ANY (ARRAY['STORE_OVERVIEW'::text, 'PRODUCT_TASK'::text, 'CLARIFY'::text]))));
ALTER TABLE ai_workbench.commands ADD CONSTRAINT commands_state_check CHECK ((state = ANY (ARRAY['READY_TO_DISPATCH'::text, 'COMPLETE'::text, 'FAILED_BEFORE_DISPATCH'::text, 'PLANNER_INVALID_OUTPUT'::text, 'PLANNER_UNKNOWN'::text, 'ROUTING_RESULT_LOST'::text])));
ALTER TABLE ai_workbench.messages ADD CONSTRAINT messages_check CHECK (((((message_kind = 'TEXT'::text) AND (store_query_status IS NULL)) OR ((message_kind = 'STORE_OVERVIEW_REF'::text) AND (author_kind = 'ASSISTANT'::text) AND (content = '店铺概况'::text) AND (store_query_status = ANY (ARRAY['ALL_NON_DELETED'::text, 'ACTIVE'::text])))) IS TRUE));
ALTER TABLE ai_workbench.messages ADD CONSTRAINT messages_message_kind_check CHECK ((message_kind = ANY (ARRAY['TEXT'::text, 'STORE_OVERVIEW_REF'::text])));
GRANT UPDATE (route_result) ON ai_workbench.commands TO ai_workbench_runtime;
